using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Xunit;

namespace MyApp.Evals;

public class ChatEvals : IAsyncLifetime
{
    private DistributedApplicationTestingBuilder _builder = null!;
    private DistributedApplication _app = null!;
    private IChatClient _chatClient = null!;
    private IChatClient _evaluatorClient = null!;

    public async Task InitializeAsync()
    {
        _builder = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _builder.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = _app.Services.GetRequiredService<IChatClient>();
    }

    public async Task DisposeAsync()
    {
        await _app.DisposeAsync();
        await _builder.DisposeAsync();
    }

    [Fact]
    public async Task Chat_RespondsRelevantly()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        Assert.Contains("Paris", responseText, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task Chat_MaintainsCoherence()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what an API is in one sentence.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        var responseText = response.Text ?? string.Empty;

        // Evaluate coherence using the AI evaluation framework
        var evaluators = new IEvaluator[] { new CoherenceEvaluator() };
        var chatTurn = new ChatTurn(messages, response.Messages);
        var result = await EvaluationExtensions.EvaluateAsync(
            evaluators, _evaluatorClient, chatTurn);

        var coherence = result.Get<NumericMetricValue>(CoherenceEvaluator.CoherenceMetricName);
        Assert.True(coherence?.NumericValue >= 3, $"Coherence score was {coherence?.NumericValue}");
    }

    [Fact]
    public async Task Chat_HandlesMultiTurnConversation()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var firstResponse = await _chatClient.GetResponseAsync(messages);
        messages.AddRange(firstResponse.Messages);
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var secondResponse = await _chatClient.GetResponseAsync(messages);
        var responseText = secondResponse.Text ?? string.Empty;

        Assert.Contains("Alice", responseText, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public async Task Chat_RelevanceEval()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "List three benefits of exercise.")
        };

        var response = await _chatClient.GetResponseAsync(messages);

        var evaluators = new IEvaluator[] { new RelevanceEvaluator() };
        var chatTurn = new ChatTurn(messages, response.Messages);
        var result = await EvaluationExtensions.EvaluateAsync(
            evaluators, _evaluatorClient, chatTurn);

        var relevance = result.Get<NumericMetricValue>(RelevanceEvaluator.RelevanceMetricName);
        Assert.True(relevance?.NumericValue >= 3, $"Relevance score was {relevance?.NumericValue}");
    }
}

